import{_ as r,D as o,c as n,I as a,a4 as i,j as t,a as l,o as d}from"./chunks/framework.CRCV4hx_.js";const w=JSON.parse('{"title":"Availability","description":"","frontmatter":{},"headers":[],"relativePath":"availability.md","filePath":"availability.md"}'),s={name:"availability.md"},c=i('<h1 id="availability" tabindex="-1">Availability <a class="header-anchor" href="#availability" aria-label="Permalink to &quot;Availability&quot;">​</a></h1><p>The Resrv Availability field is the cornerstone of the Resrv addon. It is used to bind any Entry to an availability and pricing calendar.</p><p>For multi-rate setups (room types, packages, boat types, and similar), pair this field with <a href="./rates">Rates</a>, a collection-scoped system that lets a single Entry offer several rates, each with its own availability and pricing.</p><div class="info custom-block"><p class="custom-block-title">CHANGED IN v6</p><p>The v5 &quot;Advanced availability&quot; and &quot;Connected availabilities&quot; features have been removed. Both are replaced by the new collection-scoped <a href="./rates">Rates</a> system. The <code>advanced_availability</code> and <code>connected_availabilities</code> field configs are gone, along with the <code>property</code> column. See <a href="./upgrading">Upgrading to v6</a> for the migration path.</p></div><h2 id="adding-it-to-your-blueprint" tabindex="-1">Adding it to your blueprint <a class="header-anchor" href="#adding-it-to-your-blueprint" aria-label="Permalink to &quot;Adding it to your blueprint&quot;">​</a></h2><p>Using the Blueprint Editor, add a new field of type <code>Resrv Availability</code> to your blueprint. (You can find it in the &quot;Special&quot; category).</p>',6),h=t("h2",{id:"adding-availability-pricing",tabindex:"-1"},[l("Adding availability / pricing "),t("a",{class:"header-anchor",href:"#adding-availability-pricing","aria-label":'Permalink to "Adding availability / pricing"'},"​")],-1),p=t("p",null,"After adding the field to your blueprint, simply open an Entry, and you'll see the Availability calendar.",-1),y=i("<p>You can use the <code>Enable reservations</code> toggle to disable reservations completely for this entry.</p><p>To edit the availability for this entry, simply click on the day you want to change or click and drag to select a date range. In case you want to edit more dates, there is a <code>Bulk edit</code> button at the top of the calendar.</p><p>The Bulk edit modal lets you pick a date range, set the availability and price, and optionally limit the change to specific <strong>days of the week</strong> (for example, weekend-only pricing). On an Entry with multiple rates you can also target one or more <strong>rates</strong> at once.</p><p>Each calendar day shows the remaining availability count (or <strong>Sold out</strong> when it reaches <code>0</code>) and the price for that day.</p><p>The availability modal:</p>",5),b=i('<p>The terms used here:</p><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td>Availability</td><td>The quantity of the available items (for example rooms, seats, etc.)</td></tr><tr><td>Price</td><td>The price for the selected day (or date range)</td></tr></tbody></table><p>To <em>stop sales</em> you can set the quantity to 0 or just delete the availability info for that day.</p><h2 id="per-rate-availability" tabindex="-1">Per-rate availability <a class="header-anchor" href="#per-rate-availability" aria-label="Permalink to &quot;Per-rate availability&quot;">​</a></h2><p>When an Entry has more than one <a href="./rates">rate</a>, a <strong>Rate</strong> selector appears above the calendar. Pick a rate to load and edit that rate&#39;s own availability and pricing, each rate keeps a separate calendar. With a single rate the calendar edits it directly and no selector is shown.</p><p>Rates that share their inventory with a base rate don&#39;t own availability of their own: edit the inventory on the <strong>base rate</strong>, and the shared rate draws from the same pool. (Independent prices for a shared rate are still entered here on the calendar.)</p><p>Rates themselves, creating them, choosing pricing and availability modes, restrictions, and assigning them to entries, are managed in the <strong>Rates</strong> section of the Control Panel. See <a href="./rates">Rates</a> for the full reference.</p>',7);function g(v,_,u,m,f,T){const e=o("Image");return d(),n("div",null,[c,a(e,{src:"./img/resrv-availabilty-field.webp",alt:"The Resrv Availability field in the Blueprint Editor."}),h,p,a(e,{src:"./img/resrv-availability-calendar.webp",alt:"The Availability calendar when editing availability and pricing for a date range."}),y,a(e,{src:"./img/resrv-availability-calendar-edit.webp",alt:"The Availability calendar when editing a field."}),b])}const k=r(s,[["render",g]]);export{w as __pageData,k as default};
